async function renderSimple(tab,title,description,empty){
  if(!window.beadSupabase){
    const data=adminData();
    const records=data[tab]||[];
    panel.innerHTML=`<div class="admin-heading"><div><p class="kicker">CUSTOMER OPERATIONS</p><h2>${title}</h2><p>${description}</p></div></div><div class="admin-empty">${records.length?`${records.length} records ready for review.`:empty}</div>`;
    return;
  }
  if(tab==='members'){
    const memberQuery=window.beadSupabase.from('profiles').select('id,email,full_name,status,created_at',{count:'exact'}).order('created_at',{ascending:false});
    if(selectedMemberId)memberQuery.eq('id',selectedMemberId);
    if(memberView==='new')memberQuery.gte('created_at',memberCreatedAfter);
    const memberResult=await memberQuery.range((memberPage-1)*adminPageSize,memberPage*adminPageSize-1);
    if(memberResult.error){panel.innerHTML='<div class="admin-empty">Unable to load members.</div>';return;}
    const members=memberResult.data||[];
    const memberPageCount=Math.max(1,Math.ceil((memberResult.count||0)/adminPageSize));
    memberPage=Math.min(memberPage,memberPageCount);
    const memberIds=members.map((member)=>member.id);
    const reviewsResult=memberIds.length?await window.beadSupabase.from('reviews').select('id,user_id,review_type,rating,body,photos,status,created_at,products(name)').in('user_id',memberIds).order('created_at',{ascending:false}):{data:[],error:null};
    const ordersResult=memberIds.length?await window.beadSupabase.from('orders').select('id,user_id,status,total,tracking_number,created_at').in('user_id',memberIds).order('created_at',{ascending:false}):{data:[],error:null};
    const notesResult=memberIds.length?await window.beadSupabase.from('member_notes').select('id,member_id,author_id,note,created_at').in('member_id',memberIds).order('created_at',{ascending:false}):{data:[],error:null};
    if(reviewsResult.error||ordersResult.error||notesResult.error){panel.innerHTML='<div class="admin-empty">Unable to load member details.</div>';return;}
    const reviews=reviewsResult.data||[];
    const orders=ordersResult.data||[];
    const notes=notesResult.data||[];
    const memberRows=members.map((member)=>{const memberReviews=reviews.filter((review)=>review.user_id===member.id);const memberOrders=orders.filter((order)=>order.user_id===member.id);const memberNotes=notes.filter((note)=>note.member_id===member.id);return`<article class="member-row"><div><strong>${adminSafe(member.full_name||member.email)}</strong><span>${adminSafe(member.email)}</span></div><div class="admin-actions"><button type="button" data-admin-email data-email-to="${adminSafe(member.email)}" data-email-name="${adminSafe(member.full_name||'customer')}" data-email-subject="Message from Bead Different Co.">Send email</button><button type="button" data-member-notes="${member.id}">Notes (${memberNotes.length})</button><button type="button" data-member-reviews="${member.id}">Reviews (${memberReviews.length})</button><button type="button" data-member-orders="${member.id}">Orders (${memberOrders.length})</button><button type="button" data-member-status="${member.id}" data-status="${member.status==='blocked'?'active':'blocked'}">${member.status==='blocked'?'Unblock':'Block'}</button></div></article>`}).join('')||`<div class="admin-empty">${empty}</div>`;
    panel.innerHTML=`<div class="admin-heading"><div><p class="kicker">CUSTOMER OPERATIONS</p><h2>${memberView==='new'?'New members (30 days) · ':''}${title}</h2><p>Contact customers, review their history, manage notes, and control account access.</p></div></div><div class="admin-tabs"><button type="button" data-member-view="all" class="${memberView==='all'?'active':''}">All</button><button type="button" data-member-view="new" class="${memberView==='new'?'active':''}">New (30 days)</button></div><div class="admin-list" id="member-list">${memberRows}</div><div class="admin-pagination"><button type="button" data-member-page="prev" ${memberPage<=1?'disabled':''}>Previous</button><span>Page ${memberPage} of ${memberPageCount} · ${memberResult.count||0} members</span><button type="button" data-member-page="next" ${memberPage>=memberPageCount?'disabled':''}>Next</button></div><section class="admin-card" id="member-detail"><p>Select Notes, Reviews, or Orders for a member.</p></section>`;
    panel.querySelectorAll('[data-member-view]').forEach((button)=>button.addEventListener('click',()=>{memberView=button.dataset.memberView;memberCreatedAfter=memberView==='new'?new Date(Date.now()-30*86400000).toISOString():null;memberPage=1;renderSimple(tab,title,description,empty);}));
    panel.querySelectorAll('[data-member-page]').forEach((button)=>button.addEventListener('click',()=>{memberPage+=button.dataset.memberPage==='next'?1:-1;renderSimple(tab,title,description,empty);}));
    const detail=panel.querySelector('#member-detail');
    const memberFor=(memberId)=>members.find((member)=>member.id===memberId);
    const showNotes=(memberId)=>{const member=memberFor(memberId);const memberNotes=notes.filter((note)=>note.member_id===memberId);detail.innerHTML='<h3>Notes for '+adminSafe(member?.full_name||member?.email||'member')+'</h3>'+(memberNotes.map((note)=>'<p><strong>'+new Date(note.created_at).toLocaleString()+'</strong><br>'+adminSafe(note.note)+'</p>').join('')||'<p>No notes yet.</p>')+'<form class="admin-inline-form" data-add-member-note="'+memberId+'"><input name="note" required placeholder="Add private note"><button type="submit">Save note</button><p class="admin-note-status" role="status"></p></form>';const form=detail.querySelector('form');const submit=form.querySelector('button[type="submit"]');const status=form.querySelector('.admin-note-status');form.addEventListener('submit',async(event)=>{event.preventDefault();const note=String(new FormData(form).get('note')||'').trim();if(!note){status.textContent='Enter a note first.';return;}submit.disabled=true;status.textContent='Saving…';try{const {data:{user},error:authError}=await window.beadSupabase.auth.getUser();if(authError||!user)throw authError||new Error('Your admin session has expired. Sign in again.');const result=await window.beadSupabase.from('member_notes').insert({member_id:memberId,author_id:user.id,note}).select('id,member_id,author_id,note,created_at').single();if(result.error)throw result.error;if(result.data)notes.push(result.data);const noteButton=Array.from(panel.querySelectorAll('[data-member-notes]')).find((button)=>button.dataset.memberNotes===memberId);if(noteButton)noteButton.textContent='Notes ('+notes.filter((item)=>item.member_id===memberId).length+')';showNotes(memberId);}catch(error){status.textContent='Save failed: '+(error?.message||'Unable to save note.');submit.disabled=false;}});};
    const showReviews=(memberId)=>{const member=memberFor(memberId);detail.innerHTML='<h3>Reviews by '+adminSafe(member?.full_name||member?.email||'member')+'</h3>'+(reviews.filter((review)=>review.user_id===memberId).map((review)=>'<p><strong>'+adminSafe(review.products?.name||'Website review')+' · '+review.rating+'/5 · '+adminSafe(review.status)+'</strong><br>'+adminSafe(review.body)+(review.photos||[]).map((photo)=>'<a href="'+adminSafe(photo)+'" target="_blank" rel="noreferrer"><img class="member-review-photo" src="'+adminSafe(photo)+'" alt="Customer review photo" loading="lazy"></a>').join('')+'</p>').join('')||'<p>No reviews yet.</p>');};
    const showOrders=(memberId)=>{const member=memberFor(memberId);detail.innerHTML='<h3>Orders for '+adminSafe(member?.full_name||member?.email||'member')+'</h3>'+(orders.filter((order)=>order.user_id===memberId).map((order)=>'<p><strong>Order '+adminSafe(order.id.slice(0,8))+' · $'+Number(order.total||0).toFixed(2)+'</strong><br>'+adminSafe(order.status)+' · '+new Date(order.created_at).toLocaleDateString()+' · '+adminSafe(order.tracking_number||'No tracking')+'</p>').join('')||'<p>No orders yet.</p>');};
    panel.querySelectorAll('[data-member-notes]').forEach((button)=>button.addEventListener('click',()=>showNotes(button.dataset.memberNotes)));
    panel.querySelectorAll('[data-member-reviews]').forEach((button)=>button.addEventListener('click',()=>showReviews(button.dataset.memberReviews)));
    panel.querySelectorAll('[data-member-orders]').forEach((button)=>button.addEventListener('click',()=>showOrders(button.dataset.memberOrders)));
    panel.querySelectorAll('[data-member-status]').forEach((button)=>button.addEventListener('click',async()=>{const result=await window.beadSupabase.from('profiles').update({status:button.dataset.status}).eq('id',button.dataset.memberStatus);if(result.error)return renderCloudError(result.error);renderSimple(tab,title,description,empty);}));
    return;
  }
  const thirtyDaysAgo=new Date(Date.now()-30*86400000).toISOString();
  let orderQuery=window.beadSupabase.from('orders').select('id,status,total,carrier,tracking_number,shipped_at,created_at',{count:'exact'}).order('created_at',{ascending:false});
  if(orderView==='unprocessed')orderQuery=orderQuery.in('status',['pending','paid','processing']);
  else if(orderView==='recent')orderQuery=orderQuery.gte('created_at',thirtyDaysAgo);
  const orderResult=await orderQuery.range((orderPage-1)*adminPageSize,orderPage*adminPageSize-1);
  if(orderResult.error){panel.innerHTML='<div class="admin-empty">Unable to load orders.</div>';return;}
  const orders=orderResult.data||[];
  const orderPageCount=Math.max(1,Math.ceil((orderResult.count||0)/adminPageSize));
  orderPage=Math.min(orderPage,orderPageCount);
  panel.innerHTML=`<div class="admin-heading"><div><p class="kicker">FULFILLMENT</p><h2>${title}</h2><p>${description}</p></div></div><div class="admin-tabs"><button type="button" data-order-view="unprocessed" class="${orderView==='unprocessed'?'active':''}">New/Unprocessed</button><button type="button" data-order-view="recent" class="${orderView==='recent'?'active':''}">Last 30 Days</button><button type="button" data-order-view="all" class="${orderView==='all'?'active':''}">All Orders</button></div><div class="admin-list">${orders.map((order)=>`<article><div><strong>Order ${adminSafe(order.id.slice(0,8))} · $${Number(order.total||0).toFixed(2)}</strong><span>${adminSafe(order.status)} · ${new Date(order.created_at).toLocaleDateString()}</span></div><form data-order-form="${order.id}" data-order-status="${adminSafe(order.status)}" data-order-tracking="${adminSafe(order.tracking_number||'')}" data-order-carrier="${adminSafe(order.carrier||'')}" class="admin-inline-form"><select name="status"><option ${order.status==='pending'?'selected':''}>pending</option><option ${order.status==='paid'?'selected':''}>paid</option><option ${order.status==='processing'?'selected':''}>processing</option><option ${order.status==='shipped'?'selected':''}>shipped</option><option ${order.status==='completed'?'selected':''}>completed</option><option ${order.status==='cancelled'?'selected':''}>cancelled</option><option ${order.status==='refunded'?'selected':''}>refunded</option></select><input name="carrier" value="${adminSafe(order.carrier||'')}" placeholder="Carrier"><input name="tracking_number" value="${adminSafe(order.tracking_number||'')}" placeholder="Tracking"><button type="submit">Save</button></form></article>`).join('')||`<div class="admin-empty">${empty}</div>`}</div><div class="admin-pagination"><button type="button" data-order-page="prev" ${orderPage<=1?'disabled':''}>Previous</button><span>Page ${orderPage} of ${orderPageCount} · ${orderResult.count||0} orders</span><button type="button" data-order-page="next" ${orderPage>=orderPageCount?'disabled':''}>Next</button></div>`;
  panel.querySelectorAll('[data-order-view]').forEach((button)=>button.addEventListener('click',()=>{orderView=button.dataset.orderView;orderPage=1;renderSimple(tab,title,description,empty);}));
  panel.querySelectorAll('[data-order-page]').forEach((button)=>button.addEventListener('click',()=>{orderPage+=button.dataset.orderPage==='next'?1:-1;renderSimple(tab,title,description,empty);}));
  panel.querySelectorAll('[data-order-form]').forEach((form)=>form.addEventListener('submit',async(event)=>{event.preventDefault();const fields=Object.fromEntries(new FormData(form));const changed=fields.status!==form.dataset.orderStatus||String(fields.tracking_number||'')!==String(form.dataset.orderTracking||'')||String(fields.carrier||'')!==String(form.dataset.orderCarrier||'');const result=await window.beadSupabase.from('orders').update({status:fields.status,carrier:fields.carrier||null,tracking_number:fields.tracking_number||null,shipped_at:fields.status==='shipped'?new Date().toISOString():null}).eq('id',form.dataset.orderForm);if(result.error)return renderCloudError(result.error);if(changed&&window.sendAdminStoreEmail){try{await window.sendAdminStoreEmail({action:'order_update',orderId:form.dataset.orderForm});}catch(error){window.alert(`Order saved, but the update email was not sent: ${error.message||'Unknown error.'}`);}}renderSimple(tab,title,description,empty);}));
}
async function renderCampaigns(){
  const cloud=Boolean(window.beadSupabase);
  let campaigns=[];
  let recipientCounts={all_subscribers_optins:0,member_optins:0,nonmember_subscribers:0,waitlist_product:0};
  if(cloud){
    const result=await window.beadSupabase.from('email_campaigns').select('id,subject,body,audience,status,created_at,updated_at').order('created_at',{ascending:false});
    if(result.error){panel.innerHTML='<div class="admin-empty">Unable to load email drafts.</div>';return;}
    campaigns=result.data||[];
    const [subscriberResult,preferenceResult,profileResult,waitlistResult]=await Promise.all([
      window.beadSupabase.from('notification_subscribers').select('email').eq('active',true),
      window.beadSupabase.from('customer_preferences').select('user_id').eq('marketing_opt_in',true),
      window.beadSupabase.from('profiles').select('id,email'),
      window.beadSupabase.from('waitlist_entries').select('profiles(email)').eq('status','waiting')
    ]);
    const subscriberEmails=new Set((subscriberResult.data||[]).map((row)=>String(row.email||'').trim().toLowerCase()).filter(Boolean));
    const profiles=profileResult.data||[];
    const registeredEmails=new Set(profiles.map((profile)=>String(profile.email||'').trim().toLowerCase()).filter(Boolean));
    const optedInIds=new Set((preferenceResult.data||[]).map((row)=>row.user_id));
    const memberOptins=new Set(profiles.filter((profile)=>optedInIds.has(profile.id)).map((profile)=>String(profile.email||'').trim().toLowerCase()).filter(Boolean));
    recipientCounts.all_subscribers_optins=new Set([...subscriberEmails,...memberOptins]).size;
    recipientCounts.member_optins=memberOptins.size;
    recipientCounts.nonmember_subscribers=[...subscriberEmails].filter((email)=>!registeredEmails.has(email)).length;
    recipientCounts.waitlist_product=new Set((waitlistResult.data||[]).map((row)=>row.profiles?.email).filter(Boolean).map((email)=>String(email).toLowerCase())).size;
  }
  let editingId=null;
  const recipientCount=(audience)=>recipientCounts[audience]||0;
  const audienceLabel=(audience)=>({all_subscribers_optins:'All subscribers and member opt-ins',member_optins:'Just member opt-ins',nonmember_subscribers:'Just non-member subscribers',waitlist_product:'Waitlisted customers'})[audience]||audience;
  const campaignDate=(campaign)=>{const date=new Date(campaign.created_at||'');return Number.isNaN(date.getTime())?'—':date.toLocaleDateString();};
  const statusRank=(status)=>status==='draft'||status==='queued'?0:1;
  const orderedCampaigns=()=>[...campaigns].sort((left,right)=>statusRank(left.status)-statusRank(right.status)||Date.parse(right.created_at||'')-Date.parse(left.created_at||''));
  const showEditor=(campaign)=>{
    const dialog=panel.querySelector('#campaign-editor-dialog');
    const form=dialog?.querySelector('[data-campaign-form]');
    if(!dialog||!form)return;
    editingId=campaign?.id||null;
    form.reset();
    form.elements.subject.value=campaign?.subject||'';
    form.elements.audience.value=campaign?.audience||'all_subscribers_optins';
    form.elements.body.value=campaign?.body||'';
    dialog.querySelector('[data-campaign-editor-title]').textContent=campaign?'Edit draft':'Create new draft';
    dialog.querySelector('[data-campaign-editor-status]').textContent='';
    const isSent=campaign?.status==='sent';
    form.elements.subject.disabled=isSent;
    form.elements.audience.disabled=isSent;
    form.elements.body.disabled=isSent;
    form.querySelector('[data-save-campaign]').hidden=isSent;
    dialog.querySelector('[data-campaign-editor-status]').textContent=isSent?'Sent campaigns are read-only.':'';
    dialog.showModal();
  };
  const draw=()=>{
    const rows=orderedCampaigns();
    const campaignMarkup=rows.map((campaign)=>'<article><div><strong>'+adminSafe(campaign.subject||'Untitled draft')+'</strong><span>'+adminSafe(audienceLabel(campaign.audience||''))+' · '+adminSafe(campaign.status||'draft')+' · '+campaignDate(campaign)+'</span></div><div class="admin-actions"><button type="button" data-edit-campaign="'+adminSafe(campaign.id)+'">View/Edit</button><button type="button" data-send-campaign="'+adminSafe(campaign.id)+'" '+(campaign.status==='sent'?'disabled':'')+'>'+(campaign.status==='sent'?'Sent':'Send with Resend')+'</button><button type="button" data-delete-campaign="'+adminSafe(campaign.id)+'">Delete</button></div></article>').join('')||'<div class="admin-empty">No email drafts yet.</div>';
    const dialogMarkup='<dialog class="profile-dialog" id="campaign-editor-dialog"><button type="button" class="profile-dialog-close" data-close-campaign-editor aria-label="Close editor">×</button><p class="kicker">CUSTOMER COMMUNICATION</p><h3 data-campaign-editor-title>Create new draft</h3><form class="admin-form" data-campaign-form><label>Subject<input name="subject" required></label><label>Audience<select name="audience"><option value="all_subscribers_optins">All subscribers and member opt-ins ('+recipientCounts.all_subscribers_optins+')</option><option value="member_optins">Just member opt-ins ('+recipientCounts.member_optins+')</option><option value="nonmember_subscribers">Just non-member subscribers ('+recipientCounts.nonmember_subscribers+')</option><option value="waitlist_product">Waitlisted customers ('+recipientCounts.waitlist_product+')</option></select><small data-campaign-recipient-count>Recipients: '+recipientCount('all_subscribers_optins')+'</small></label><label>Message<textarea name="body" rows="8" required></textarea></label><div class="profile-dialog-actions"><button type="submit" class="cta" data-save-campaign>Save draft</button><button type="button" data-close-campaign-editor>Cancel</button></div><p data-campaign-editor-status role="status"></p></form></dialog>';
    panel.innerHTML='<div class="admin-heading"><div><p class="kicker">CUSTOMER COMMUNICATION</p><h2>Email drafts</h2><p>Create announcements for opted-in subscribers or waitlisted customers. Resend delivery is connected through the store email function.</p></div><button type="button" class="cta" data-create-campaign>Create new draft</button></div><div class="admin-list">'+campaignMarkup+'</div>'+dialogMarkup;
    const dialog=panel.querySelector('#campaign-editor-dialog');
    const form=dialog.querySelector('[data-campaign-form]');
    const updateRecipientCount=()=>{dialog.querySelector('[data-campaign-recipient-count]').textContent='Recipients: '+recipientCount(form.elements.audience.value);};
    panel.querySelector('[data-create-campaign]').addEventListener('click',()=>showEditor(null));
    panel.querySelectorAll('[data-edit-campaign]').forEach((button)=>button.addEventListener('click',()=>showEditor(campaigns.find((campaign)=>String(campaign.id)===button.dataset.editCampaign))));
    dialog.querySelectorAll('[data-close-campaign-editor]').forEach((button)=>button.addEventListener('click',()=>dialog.close()));
    dialog.addEventListener('click',(event)=>{if(event.target===dialog)dialog.close();});
    form.elements.audience.addEventListener('change',updateRecipientCount);
    form.addEventListener('submit',async(event)=>{
      event.preventDefault();
      const fields=Object.fromEntries(new FormData(form));
      const status=dialog.querySelector('[data-campaign-editor-status]');
      if(!fields.subject?.trim()||!fields.body?.trim()){status.textContent='Enter a subject and message.';return;}
      status.textContent='Saving draft…';
      try{
        if(cloud){
          if(editingId){
            const result=await window.beadSupabase.from('email_campaigns').update({subject:fields.subject.trim(),body:fields.body.trim(),audience:fields.audience,updated_at:new Date().toISOString()}).eq('id',editingId).select('id,subject,body,audience,status,created_at,updated_at').single();
            if(result.error)throw result.error;
            campaigns=campaigns.map((campaign)=>campaign.id===editingId?result.data:campaign);
          }else{
            const {data:{user}}=await window.beadSupabase.auth.getUser();
            const result=await window.beadSupabase.from('email_campaigns').insert({author_id:user.id,subject:fields.subject.trim(),body:fields.body.trim(),audience:fields.audience,status:'draft'}).select('id,subject,body,audience,status,created_at,updated_at').single();
            if(result.error)throw result.error;
            campaigns.unshift(result.data);
          }
        }else if(editingId){
          campaigns=campaigns.map((campaign)=>campaign.id===editingId?{...campaign,subject:fields.subject.trim(),body:fields.body.trim(),audience:fields.audience,updated_at:new Date().toISOString()}:campaign);
        }else{
          campaigns.unshift({subject:fields.subject.trim(),body:fields.body.trim(),audience:fields.audience,id:'draft-'+Date.now(),status:'draft',created_at:new Date().toISOString()});
        }
        dialog.close();
        draw();
      }catch(error){status.textContent='Draft was not saved: '+(error.message||'Unknown error.');}
    });
    panel.querySelectorAll('[data-delete-campaign]').forEach((button)=>button.addEventListener('click',async()=>{
      if(!window.confirm('Delete this email draft?'))return;
      if(cloud){
        const result=await window.beadSupabase.from('email_campaigns').delete().eq('id',button.dataset.deleteCampaign);
        if(result.error){dialog.querySelector('[data-campaign-editor-status]').textContent='Draft was not deleted: '+result.error.message;return;}
      }
      campaigns=campaigns.filter((campaign)=>String(campaign.id)!==button.dataset.deleteCampaign);
      draw();
    }));
  };
  draw();
}
const renderSubscribers=async()=>{
  const cloud=Boolean(window.beadSupabase);
  let records=[];
  if(cloud){
    const [subscriberResult,profileResult,preferenceResult]=await Promise.all([
      window.beadSupabase.from('notification_subscribers').select('email,active,source,created_at').order('created_at',{ascending:false}),
      window.beadSupabase.from('profiles').select('id,email,full_name,created_at').order('created_at',{ascending:false}),
      window.beadSupabase.from('customer_preferences').select('user_id,marketing_opt_in')
    ]);
    if(subscriberResult.error||profileResult.error||preferenceResult.error){panel.innerHTML='<div class="admin-empty">Unable to load newsletter subscribers.</div>';return;}
    const members=new Map((profileResult.data||[]).map((profile)=>[profile.id,profile]));
    const membersByEmail=new Map((profileResult.data||[]).filter((profile)=>profile.email).map((profile)=>[String(profile.email).trim().toLowerCase(),profile]));
    const optedIn=new Set((preferenceResult.data||[]).filter((preference)=>preference.marketing_opt_in).map((preference)=>preference.user_id));
    const byEmail=new Map();
    (subscriberResult.data||[]).filter((subscriber)=>subscriber.active).forEach((subscriber)=>{
      const key=String(subscriber.email||'').trim().toLowerCase();
      const profile=membersByEmail.get(key);
      byEmail.set(key,{email:subscriber.email,name:profile?.full_name||'',source:profile?'Member · '+subscriber.source:subscriber.source,created_at:subscriber.created_at,memberId:profile?.id});
    });
    optedIn.forEach((userId)=>{
      const profile=members.get(userId);
      if(!profile?.email)return;
      const key=String(profile.email).trim().toLowerCase();
      const existing=byEmail.get(key);
      if(existing){existing.name=profile.full_name||existing.name;existing.memberId=profile.id;existing.source='Member opt-in'+(existing.source?' · '+existing.source:'');}
      else byEmail.set(key,{email:profile.email,name:profile.full_name||'',source:'Member opt-in',created_at:profile.created_at,memberId:profile.id});
    });
    records=[...byEmail.values()];
  }else{
    const localSubscribers=JSON.parse(localStorage.getItem('beadDifferentNotificationSubscribers')||'[]');
    records=localSubscribers.map((email)=>({email,source:'footer',name:'',created_at:null}));
  }
  const draw=()=>{
    const needle=(panel.querySelector('[data-subscriber-search]')?.value||'').trim().toLowerCase();
    const filtered=records.filter((record)=>[record.email,record.name,record.source].filter(Boolean).join(' ').toLowerCase().includes(needle));
    const pageCount=Math.max(1,Math.ceil(filtered.length/adminPageSize));
    subscriberPage=Math.min(subscriberPage,pageCount);
    const page=filtered.slice((subscriberPage-1)*adminPageSize,subscriberPage*adminPageSize);
    const tableRows=page.map((record)=>{
      const display=record.name||record.email||'Subscriber';
      const subscriberCell=record.memberId?'<a href="admin.html?member='+encodeURIComponent(record.memberId)+'">'+adminSafe(display)+'</a>':adminSafe(display);
      return '<tr><td>'+subscriberCell+'</td><td>'+adminSafe(record.source||'—')+'</td><td>'+adminSafe(record.created_at?new Date(record.created_at).toLocaleDateString():'—')+'</td></tr>';
    }).join('')||'<tr><td colspan="3">No subscribers found.</td></tr>';
    panel.innerHTML='<div class="admin-heading"><div><p class="kicker">CUSTOMER COMMUNICATION</p><h2>Newsletter Subscribers</h2><p>Newsletter signups and members who opted in to product drops, restocks, and promotions.</p></div></div><div class="admin-form-grid"><label>Search subscribers<input type="search" data-subscriber-search placeholder="Name or email"></label></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Subscriber</th><th>Source</th><th>Joined</th></tr></thead><tbody>'+tableRows+'</tbody></table></div><div class="admin-pagination"><button type="button" data-subscriber-page="prev" '+(subscriberPage<=1?'disabled':'')+'>Previous</button><span>Page '+subscriberPage+' of '+pageCount+'</span><button type="button" data-subscriber-page="next" '+(subscriberPage>=pageCount?'disabled':'')+'>Next</button></div>';
    panel.querySelector('[data-subscriber-search]').addEventListener('input',()=>{subscriberPage=1;draw();});
    panel.querySelectorAll('[data-subscriber-page]').forEach((button)=>button.addEventListener('click',()=>{subscriberPage+=button.dataset.subscriberPage==='next'?1:-1;draw();}));
  };
  draw();
};
function clearAdminRoute(){const url=new URL(window.location.href);url.search='';history.replaceState({},'',url.href);}
