    orders=Object.values(adminData().orders||{});etsyMappings=[];inventoryRecords=products.filter((product)=>product.sku).map((product)=>({id:product.id,sku:product.sku,name:product.name,quantity_on_hand:product.quantity,reorder_point:product.low_stock_threshold,price:product.price,cost:product.estimated_cost,category:product.category_slug,preferred_vendor:'',unit_type:'Each',weight_value:null,weight_unit:'oz'}));bundleComponents=[];etsySales=[];manualAllocations=[];
