const renderAdminPromoEditor=(form,promoSkus=[])=>{const list=form.querySelector('[data-promo-sku-list]');let selected=new Set((promoSkus||[]).map((sku)=>String(sku).toLowerCase()));const sync=()=>{const current=[...list.querySelectorAll('[data-promo-sku]:checked')].map((input)=>input.value);selected=new Set(current.map((sku)=>String(sku).toLowerCase()));form.elements.promo_skus.value=JSON.stringify(current);};const draw=()=>{const rows=JSON.parse(form.elements.sku_data.value||'[]').flatMap((option)=>option.values||[]).filter((value)=>value.sku);list.innerHTML=rows.length?rows.map((value)=>'<label><input type="checkbox" data-promo-sku value="'+adminSafe(value.sku)+'" '+(selected.has(String(value.sku).toLowerCase())?'checked':'')+'> '+adminSafe(value.label)+' ('+adminSafe(value.sku)+')</label>').join(''):'<p>Add SKUs above before assigning a promo.</p>';list.querySelectorAll('[data-promo-sku]').forEach((input)=>input.addEventListener('change',sync));sync();};form.addEventListener('sku-list-changed',draw);draw();};
const organizeAdminBadges=(form)=>{const fieldset=form.querySelector('.admin-badge-picker');if(!fieldset||fieldset.dataset.organized)return;fieldset.dataset.organized='true';const groups=[['Qty sold by',['Single Bead','Multi-Pack']],['Material',['Silicone','Acrylic','Rhinestones']],['Size',['10mm','12mm','12mm Lentil','14mm','14mm Abacus','15mm','16mm','18mm','20mm']],['Inventory status',['Clearance']],['Other',['Fits on Beadable Pen']]];const labels=new Map([...fieldset.querySelectorAll(':scope > label')].map((label)=>[label.querySelector('input')?.value,label]));const legend=fieldset.querySelector('legend');fieldset.replaceChildren(legend);groups.forEach(([title,values])=>{const group=document.createElement('div');group.className='admin-badge-group admin-badge-group-'+adminSlug(title);const heading=document.createElement('h4');heading.textContent=title;group.append(heading);values.forEach((value)=>{let label=labels.get(value);if(!label){label=document.createElement('label');label.innerHTML='<input type="checkbox" name="badges" value="'+adminSafe(value)+'"> <span class="product-badge badge-'+adminSlug(value)+'">'+adminSafe(value)+'</span>';}label.classList.add('admin-badge-option','admin-badge-option-'+adminSlug(value));group.append(label);});fieldset.append(group);});};
const renderAdminMediaPreviews=(form)=>{const openImage=(url,alt)=>{const dialog=document.createElement('dialog');dialog.className='admin-media-viewer';const image=document.createElement('img');image.src=url;image.alt=alt||'Enlarged media preview';dialog.append(image);dialog.addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>dialog.remove(),{once:true});document.body.append(dialog);dialog.showModal();};const renderRow=(row)=>{row.querySelector('[data-media-preview]')?.remove();const url=row.querySelector('[data-existing-url]')?.value.trim()||row.querySelector('[data-manual-url]')?.value.trim();const type=row.querySelector('[data-existing-type]')?.value||row.querySelector('[data-manual-type]')?.value||'image';if(!url)return;const preview=type==='video'?document.createElement('video'):document.createElement('img');preview.dataset.mediaPreview='';preview.className='admin-media-preview';preview.src=url;if(type==='video'){preview.controls=true;preview.preload='metadata';}else{preview.alt='Media preview';preview.title='Click to enlarge';preview.addEventListener('click',()=>openImage(url,preview.alt));}row.prepend(preview);};form.querySelectorAll('[data-existing-media],[data-manual-media]').forEach((row)=>{renderRow(row);});form.addEventListener('input',(event)=>{const row=event.target.closest('[data-existing-media],[data-manual-media]');if(row&&(event.target.matches('[data-existing-url],[data-manual-url]')))renderRow(row);});form.addEventListener('change',(event)=>{const row=event.target.closest('[data-existing-media],[data-manual-media]');if(row&&(event.target.matches('[data-existing-type],[data-manual-type]')))renderRow(row);});const fileInput=form.querySelector('[name=media]');if(fileInput){fileInput.addEventListener('change',()=>{form.querySelector('[data-upload-preview]')?.remove();const wrapper=document.createElement('div');wrapper.dataset.uploadPreview='';wrapper.className='admin-upload-previews';Array.from(fileInput.files||[]).forEach((file)=>{const preview=file.type.startsWith('video/')?document.createElement('video'):document.createElement('img');preview.className='admin-media-preview';preview.src=URL.createObjectURL(file);if(preview.tagName==='VIDEO'){preview.controls=true;preview.muted=true;}else{preview.alt=file.name;preview.title='Click to enlarge';preview.addEventListener('click',()=>openImage(preview.src,file.name));}wrapper.append(preview);});fileInput.parentElement.append(wrapper);});}};
const renderAdminInventoryHistory=async(form)=>{const productId=form?.dataset.productId;if(!productId||form.dataset.inventoryHistoryLoaded)return;form.dataset.inventoryHistoryLoaded='loading';const [changeResult,adjustmentResult]=await Promise.all([cloudAdmin().from('product_change_history').select('id,inventory_sku,field_name,previous_value,new_value,change_type,note,created_at').eq('product_id',productId).order('created_at',{ascending:false}).range(0,199),cloudAdmin().from('inventory_adjustments').select('id,inventory_sku,quantity_delta,quantity_after,note,adjustment_type,cost_impact,created_at').eq('product_id',productId).order('created_at',{ascending:false}).range(0,199)]);if(!form.isConnected)return;if(changeResult.error||adjustmentResult.error){form.dataset.inventoryHistoryLoaded='error';return;}const entries=[...(changeResult.data||[]).map((entry)=>({...entry,historyType:'change'})),...(adjustmentResult.data||[]).map((entry)=>({inventory_sku:entry.inventory_sku,field_name:'Inventory quantity',previous_value:String(Number(entry.quantity_after)-Number(entry.quantity_delta)),new_value:String(entry.quantity_after),change_type:'updated',note:entry.note,adjustment_type:entry.adjustment_type,cost_impact:entry.cost_impact,created_at:entry.created_at,historyType:'adjustment'}))].sort((first,second)=>Date.parse(second.created_at)-Date.parse(first.created_at));const formatEntry=(entry)=>'<li><strong>'+adminSafe(entry.field_name)+'</strong><span>'+adminSafe(entry.inventory_sku||'Product')+' · '+new Date(entry.created_at).toLocaleString()+' · '+adminSafe(entry.change_type)+'</span><p>Previous: '+adminSafe(entry.previous_value??'—')+' → New: '+adminSafe(entry.new_value??'—')+(entry.note?' · '+adminSafe(entry.note):'')+(entry.historyType==='adjustment'?' · Source: '+adminSafe(String(entry.adjustment_type||'manual').replace(/_/g,' '))+(Number(entry.cost_impact)?' · Cost impact: $'+Number(entry.cost_impact).toFixed(2):''):'')+'</p></li>';const section=document.createElement('details');section.className='admin-card admin-inventory-history';section.innerHTML='<summary>Product change history</summary><p>Important product and inventory changes recorded for review.</p><ul>'+((entries.map(formatEntry).join(''))||'<li>No product changes recorded.</li>')+'</ul>';const actions=form.querySelector('.admin-actions');if(actions)actions.before(section);else form.append(section);form.dataset.inventoryHistoryLoaded='true';};
const initializeAdminSkuLayout=(form)=>{form.querySelectorAll('[data-variant-row]').forEach((row)=>{if(row.dataset.skuLayoutInitialized)return;const markField=(selector,className)=>{const label=row.querySelector(selector)?.closest('label');label?.classList.add(className);return label;};const nameLabel=markField('[data-variant-label]','admin-sku-name-field');markField('[data-variant-sku]','admin-sku-sku-field');const priceLabel=markField('[data-variant-price]','admin-sku-price-field');const priceInput=row.querySelector('[data-variant-price]');const unitInput=row.querySelector('[data-variant-unit-type]');const priceUnitWrap=unitInput?.closest('.admin-price-unit');if(priceLabel&&priceInput&&unitInput&&priceUnitWrap){priceUnitWrap.replaceWith(priceInput);const unitLabel=document.createElement('label');unitLabel.className='admin-sku-unit-field';unitLabel.append('Unit',unitInput);priceLabel.after(unitLabel);}const weightLabel=markField('[data-variant-weight]','admin-sku-weight-field');const weightInput=row.querySelector('[data-variant-weight]');const weightUnitLabel=row.querySelector('[data-variant-weight-unit]')?.closest('label');const weightUnitInput=row.querySelector('[data-variant-weight-unit]');if(weightLabel&&weightInput&&weightUnitLabel&&weightUnitInput){const weightInputs=document.createElement('div');weightInputs.className='admin-sku-weight-inputs';weightInput.replaceWith(weightInputs);weightInputs.append(weightInput,weightUnitInput);weightUnitLabel.remove();}const cost=row.querySelector('.admin-sku-cost');const costInput=cost?.querySelector('[data-variant-cost]');if(cost&&costInput){const costLabel=document.createElement('label');costLabel.className='admin-sku-cost-field';costLabel.append('Cost',costInput);cost.replaceWith(costLabel);weightLabel?.after(costLabel);}markField('[data-variant-quantity]','admin-sku-inventory-field');const thresholdLabel=markField('[data-variant-threshold]','admin-sku-threshold-field');const reserveInput=row.querySelector('[data-variant-reserve]');const reserveLabel=reserveInput?.closest('label');if(reserveInput&&reserveLabel&&thresholdLabel){const reserveField=document.createElement('label');reserveField.className='admin-sku-reserve-field';reserveField.append('Reserve buffer',reserveInput);reserveLabel.remove();thresholdLabel.after(reserveField);}markField('[data-variant-inventory-sku]','admin-sku-affected-field');markField('[data-variant-inventory-units]','admin-sku-deducted-field');markField('[data-variant-photo]','admin-sku-photo-field');['[data-variant-cost]','[data-variant-unit-type]','[data-variant-quantity]','[data-variant-item-type]'].forEach((selector)=>{const field=row.querySelector(selector);if(!field)return;field.readOnly=field.tagName!=='SELECT';field.disabled=field.tagName==='SELECT';field.classList.add('admin-sku-locked-field');field.title='Edit in Inventory adjustments';});row.dataset.skuLayoutInitialized='true';});};

