const installStateTaxMetrics=async()=>{
  if(activeTab!=='stats'||!panel.querySelector('#metrics-report')||panel.querySelector('[data-state-tax-metrics]'))return;
  const section=document.createElement('section');
  section.className='admin-card';
  section.dataset.stateTaxMetrics='loading';
  section.innerHTML='<div class="admin-heading"><div><h3>State order and tax tracking</h3><p>Order count, order total, and tax collected by shipping state.</p></div><button type="button" data-download-state-tax>Download CSV</button></div><p data-state-tax-status>Loading state totals…</p><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>State</th><th>Order qty</th><th>Order total</th><th>Tax collected</th></tr></thead><tbody></tbody></table></div>';
  panel.append(section);
  try{
    const orders=await fetchAdminRowsAll(()=>cloudAdmin().from('orders').select('id,status,total,tax_amount,shipping_address').order('created_at',{ascending:false}));
    const grouped=new Map();
    for(const order of orders){
      if(['cancelled','refunded'].includes(String(order.status||'').toLowerCase()))continue;
      const rawState=String(order.shipping_address?.state||'').trim().toUpperCase();
      const state=rawState==='OHIO'?'OH':rawState||'Unknown';
      const row=grouped.get(state)||{state,orders:0,total:0,tax:0};
      row.orders+=1;row.total+=Number(order.total)||0;row.tax+=Number(order.tax_amount)||0;grouped.set(state,row);
    }
    const rows=[...grouped.values()].sort((left,right)=>left.state.localeCompare(right.state));
    section.querySelector('tbody').innerHTML=rows.map((row)=>'<tr><td>'+adminSafe(row.state)+'</td><td>'+row.orders+'</td><td>$'+row.total.toFixed(2)+'</td><td>$'+row.tax.toFixed(2)+'</td></tr>').join('')||'<tr><td colspan="4">No orders recorded yet.</td></tr>';
    section.querySelector('[data-state-tax-status]').textContent=rows.length+' state'+(rows.length===1?'':'s')+' tracked.';
    section.querySelector('[data-download-state-tax]').onclick=()=>download([['State','Order qty','Order total','Tax collected'],...rows.map((row)=>[row.state,row.orders,row.total.toFixed(2),row.tax.toFixed(2)])],'state-order-tax-report.csv');
    section.dataset.stateTaxMetrics='ready';
  }catch(error){section.querySelector('[data-state-tax-status]').textContent='Unable to load state order and tax totals: '+(error.message||'Unknown error.');section.dataset.stateTaxMetrics='error';}
};
