const saveAdminSkuDisposition=async(row)=>{if(!row||row.dataset.setupLocked==='true'||!window.beadSupabase)return;const sku=String(row.querySelector('[data-variant-inventory-sku]')?.value||row.querySelector('[data-variant-sku]')?.value||'').trim();const disposition=String(row.querySelector('[data-variant-disposition]')?.value||'unresolved');const target=String(row.querySelector('[data-variant-predetermined-sku]')?.value||'').trim();const typeInput=row.querySelector('[data-variant-item-type]');if(typeInput)typeInput.value=['recipe_parent','predetermined_random'].includes(disposition)?'Non-inventory':'Inventory';const result=await cloudAdmin().from('inventory_skus').select('id').ilike('sku',sku).maybeSingle();if(result.error||!result.data)return;const applied=await cloudAdmin().rpc('apply_inventory_sku_disposition',{inventory_sku_id:result.data.id,disposition,predetermined_sku_value:target||null});if(applied.error){row.dataset.dispositionError=applied.error.message;return;}row.dataset.dispositionError='';delete row.dataset.setupLockSku;void initializeAdminSkuSetupLocks();};new MutationObserver(()=>initializeAdminSkuSetupLocks()).observe(panel,{childList:true,subtree:true});initializeAdminSkuSetupLocks();
