const initializeAdminActiveThemeSelection=()=>{const form=panel?.querySelector('[data-theme-form]');const select=form?.elements?.theme_preset;if(!form||!select||select.dataset.activeThemeReady)return;select.dataset.activeThemeReady='true';const normalizePhotos=(value)=>value&&typeof value==='object'?value:{};const selectActive=()=>{const settings=adminData().settings||{};const config=window.productStoreConfig||{};const presets=Array.isArray(settings.themePresets)?settings.themePresets:[];const active=normalizeAdminTheme(settings.theme||config.theme);const snapshot=settings.themeDefaultSnapshot||{};if(JSON.stringify(active)===JSON.stringify(normalizeAdminTheme(snapshot.theme||{}))&&select.querySelector('[value="__locked_default__"]')){select.value='__locked_default__';return;}const index=presets.findIndex((preset)=>JSON.stringify(normalizeAdminTheme(preset?.theme||{}))===JSON.stringify(active));if(index>=0&&select.options[index+2])select.value=String(index);};const loadDefaultCategoryPreviews=async()=>{if(select.value!=='__locked_default__'||!window.beadSupabase)return;const result=await cloudAdmin().from('categories').select('slug,cover_photo');if(result.error)return;const photos=Object.fromEntries((result.data||[]).map((category)=>[category.slug,safeAdminThemeImageUrl(category.cover_photo)]));form.querySelectorAll('[data-theme-category]').forEach((input)=>{const preview=input.nextElementSibling;if(preview?.matches('img.admin-theme-category-preview')&&photos[input.dataset.themeCategory]){preview.hidden=false;preview.src=photos[input.dataset.themeCategory];}});};select.addEventListener('change',()=>{void loadDefaultCategoryPreviews();});selectActive();void loadDefaultCategoryPreviews();};new MutationObserver(()=>initializeAdminActiveThemeSelection()).observe(panel,{childList:true,subtree:true});initializeAdminActiveThemeSelection();
